begin;
select plan(37);
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000101','orders-staff@example.test'),('00000000-0000-4000-8000-000000000102','orders-brand@example.test'),('00000000-0000-4000-8000-000000000103','orders-accounting@example.test');
update public.profiles set role='staff' where id='00000000-0000-4000-8000-000000000101';
update public.profiles set role='accounting' where id='00000000-0000-4000-8000-000000000103';
insert into public.brands(id,name) values('00000000-0000-4000-8000-000000000104','Orders A'),('00000000-0000-4000-8000-000000000105','Orders B');
insert into public.brand_users(brand_id,user_id) values('00000000-0000-4000-8000-000000000104','00000000-0000-4000-8000-000000000102');
insert into public.customers(id,legal_name,city,notes,vat_number) values('00000000-0000-4000-8000-000000000106','Public customer name','Milano','Private buyer notes','12345678901');
insert into public.seasons(id,brand_id,code,name) values('00000000-0000-4000-8000-000000000107','00000000-0000-4000-8000-000000000104','ORDER-TEST','Season A'),('00000000-0000-4000-8000-000000000108','00000000-0000-4000-8000-000000000105','ORDER-TEST','Season B');
insert into public.products(id,brand_id,season_id,sku_base,name,wholesale_price_cents,vat_rate) values('00000000-0000-4000-8000-000000000109','00000000-0000-4000-8000-000000000104','00000000-0000-4000-8000-000000000107','ORD-TEST','Shirt',1999,22);
insert into public.product_variants(id,brand_id,product_id,size,color,sku) values('00000000-0000-4000-8000-000000000110','00000000-0000-4000-8000-000000000104','00000000-0000-4000-8000-000000000109','M','Blu','ORD-TEST-M-BLU');
create temp table test_orders(id uuid,other_id uuid,header jsonb,lines jsonb);
grant all on test_orders to authenticated;
insert into test_orders(header,lines) values('{"brand_id":"00000000-0000-4000-8000-000000000104","customer_id":"00000000-0000-4000-8000-000000000106","season_id":"00000000-0000-4000-8000-000000000107","order_date":"2026-10-12","delivery_date":"","payment_terms":"30 giorni","discount_pct":10,"commission_pct_override":12.5,"internal_notes":"Private commission and notes"}','[{"variant_id":"00000000-0000-4000-8000-000000000110","quantity":3,"unit_price_cents":1999,"discount_pct":12.5}]');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000101';
select lives_ok($$update test_orders set id=public.save_order(null,header,lines)$$,'order and lines save atomically');
select is((select net_total_cents from public.orders where id=(select id from test_orders)),4723::bigint,'combined discounts round once to cents');
select is((select vat_total_cents from public.orders where id=(select id from test_orders)),1039::bigint,'VAT rounds on the discounted line');
select is((select gross_total_cents from public.orders where id=(select id from test_orders)),5762::bigint,'gross is net plus VAT');
select matches((select number from public.orders where id=(select id from test_orders)),'^2026/[0-9]{5,}$','annual number assigned by database');
select lives_ok($$update public.orders set discount_pct=0 where id=(select id from test_orders)$$,'header discount recalculates line totals');
select is((select net_total_cents from public.orders where id=(select id from test_orders)),5247::bigint,'header discount refreshes net total');
update public.orders set net_total_cents=1,gross_total_cents=1 where id=(select id from test_orders);
select is((select net_total_cents from public.orders where id=(select id from test_orders)),5247::bigint,'caller cannot forge totals');
update public.order_lines set vat_rate=100 where order_id=(select id from test_orders);
select is((select vat_rate from public.order_lines where order_id=(select id from test_orders)),22::numeric,'VAT snapshot cannot be forged');
select throws_ok($$select public.change_order_status(id,'shipped','') from test_orders$$,'23514',null,'invalid transition fails in database');
select lives_ok($$select public.change_order_status(id,'confirmed','Customer approved') from test_orders$$,'draft confirms');
select throws_ok($$update public.order_lines set quantity=9 where order_id=(select id from test_orders)$$,'23514',null,'confirmed lines are immutable');
select throws_ok($$update public.orders set discount_pct=20 where id=(select id from test_orders)$$,'23514',null,'confirmed financial header is immutable');
select is((select count(*) from public.order_status_history where order_id=(select id from test_orders)),2::bigint,'initial state and transition recorded');
update test_orders set other_id=public.save_order(null,jsonb_set(jsonb_set(header,'{brand_id}','"00000000-0000-4000-8000-000000000105"'),'{season_id}','"00000000-0000-4000-8000-000000000108"'),'[]');
select throws_ok($$select public.save_order(null,header,lines || '[{"variant_id":"00000000-0000-4000-8000-000000000111","quantity":1,"unit_price_cents":100,"discount_pct":0}]') from test_orders$$,'23514',null,'error after first line aborts the whole order');
select is((select count(*) from public.orders where brand_id in('00000000-0000-4000-8000-000000000104','00000000-0000-4000-8000-000000000105')),2::bigint,'failed order leaves no partial header');
select is((select count(*) from public.order_lines where brand_id='00000000-0000-4000-8000-000000000104'),1::bigint,'failed order leaves no partial lines');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000102';
select is((select count(*) from public.orders where id in(select id from test_orders union all select other_id from test_orders)),1::bigint,'brand only reads its own orders');
select is((select count(*) from public.order_private),0::bigint,'brand cannot read notes or commissions');
select is((select count(*) from public.customers),0::bigint,'brand never reads customer table');
select is((select customer_display_name from public.portal_orders where id=(select id from test_orders)),'Public customer name','portal only reveals permitted customer name');
select is(app.portal_customer((select other_id from test_orders)),null::jsonb,'customer helper refuses another brand order');
select throws_ok($$select public.change_order_status(id,'in_production','') from test_orders$$,'42501',null,'brand cannot change status');
reset role;
update public.brands set can_see_customer_names=false where id='00000000-0000-4000-8000-000000000104';
set local role authenticated;
select is((select customer_display_name from public.portal_orders where id=(select id from test_orders)),'Cliente riservato','privacy flag hides customer name');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000103';
select throws_ok($$select public.change_order_status(id,'in_production','') from test_orders$$,'42501',null,'accounting cannot advance production');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000101';
select public.change_order_status(id,'in_production','') from test_orders;
select public.change_order_status(id,'shipped','') from test_orders;
select public.change_order_status(id,'delivered','') from test_orders;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000103';
select lives_ok($$select public.change_order_status(id,'invoiced','') from test_orders$$,'accounting invoices delivered order');
select throws_ok($$select public.change_order_status(id,'cancelled','') from test_orders$$,'42501',null,'accounting cannot cancel final invoice');
select throws_ok($$insert into public.order_status_history(order_id,brand_id,to_status) values((select id from test_orders),'00000000-0000-4000-8000-000000000104','cancelled')$$,'42501',null,'history cannot be forged');

select throws_ok($$select public.duplicate_order(id) from test_orders$$,'42501',null,'accounting cannot duplicate');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000102';
select throws_ok($$select public.duplicate_order(id) from test_orders$$,'42501',null,'brand cannot duplicate');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000101';
select lives_ok($$update test_orders set other_id=public.duplicate_order(id)$$,'staff duplicates final order atomically');
select is((select status::text from public.orders where id=(select other_id from test_orders)),'draft','copy starts in draft');
select isnt((select number from public.orders where id=(select other_id from test_orders)),(select number from public.orders where id=(select id from test_orders)),'copy receives a new number');
select is((select internal_notes from public.order_private where id=(select other_id from test_orders)),'Private commission and notes','copy preserves private fields');
select is((select unit_price_cents from public.order_lines where order_id=(select other_id from test_orders)),1999::bigint,'copy preserves agreed price');
update public.product_variants set deleted_at=now() where id='00000000-0000-4000-8000-000000000110';
select throws_ok($$select public.duplicate_order(id) from test_orders$$,'23514',null,'archived variant refuses duplication');
select is((select count(*) from public.orders where brand_id='00000000-0000-4000-8000-000000000104'),2::bigint,'failed duplication leaves no partial copy');
select * from finish();rollback;
